  "Ramsay Health Care": { about: ["Ramsay Health Care is a global private hospital operator that began in Sydney. In Australia it runs a large network of private hospitals and day surgeries, providing surgery, mental health care, maternity, rehabilitation and other services.", "It employs nurses and midwives, doctors and allied health staff, theatre and surgical staff, patient services and hospitality staff, and corporate and technology staff. Most roles are in hospitals around the country, and graduate nurse programs are run each year."], spec: ["Private hospitals", "Surgery", "Mental health", "Maternity", "Rehabilitation"], hq: "Sydney, NSW", roles: ["Registered nurse", "Midwife", "Theatre nurse", "Allied health", "Patient services"] },
  "Tasmanian Health Service": { about: ["The Tasmanian Health Service runs the state's public hospitals and community health services, including the Royal Hobart Hospital, the Launceston General Hospital, the North West Regional Hospital and the Mersey Community Hospital. It also provides mental health, primary care and community services.", "It employs doctors, nurses and midwives, allied health professionals, paramedic and community staff, orderlies and support staff, and corporate and technology staff. Jobs are advertised on the Tasmanian Government jobs site, and nursing and allied health graduate programs are run each year."], spec: ["Public hospitals", "Community health", "Mental health", "Nursing and midwifery", "Allied health"], hq: "Hobart, TAS", roles: ["Registered nurse", "Doctor", "Allied health", "Midwife", "Support staff"] },
  "Virtus Health": { about: ["Virtus Health is an Australian fertility services provider. It runs fertility clinics and IVF laboratories in Australia and overseas, helping couples and individuals with fertility treatment, and also offers genetic testing and related services.", "It employs fertility specialists, nurses and midwives, embryologists and scientists, genetic counsellors, clinic and administration staff, patient care coordinators, and corporate and technology staff. Embryologist roles need a science degree, and many roles are in clinics in capital cities and regional areas."], spec: ["Fertility treatment", "IVF laboratories", "Embryology", "Patient care", "Genetic testing"], roles: ["Nurse", "Embryologist", "Fertility specialist", "Patient coordinator", "Clinic administration"] },
  "Hearing Australia": { about: ["Hearing Australia is a federal agency that provides hearing services to Australians, particularly children and young people, older people on government programs and Aboriginal and Torres Strait Islander people. It tests hearing, fits hearing aids, runs research and offers services through hearing centres and outreach clinics.", "It employs audiologists, audiometrists, clinic and customer service staff, research scientists, engineers, outreach staff, and corporate and technology staff. Audiologist roles need a postgraduate qualification, and many roles are in centres in cities and regional towns."], spec: ["Audiology", "Hearing aids", "Paediatric hearing", "Outreach", "Research"], hq: "Sydney, NSW", roles: ["Audiologist", "Audiometrist", "Customer service", "Researcher", "Clinic administration"] },

